    "path": "src/Utils/ArrayOperations.cs",
    "content": "using System;

namespace Utils
{
    public static class ArrayOperations
    {
        /// <summary>
        /// Sorts an array of doubles in ascending order and then multiplies each element by 3.
        /// </summary>
        /// <param name="arr">The array of doubles to process. Must not be null.</param>
        /// <returns>A new array containing the sorted and multiplied values.</returns>
        /// <exception cref="ArgumentNullException">If arr is null.</exception>
        public static double[] SortAndMultiplyBy3(double[] arr)
        {
            if (arr == null)
                throw new ArgumentNullException(nameof(arr));

            // Create a copy to avoid modifying the original array
            double[] result = (double[])arr.Clone();
            Array.Sort(result);
            for (int i = 0; i < result.Length; i++)
            {
                result[i] *= 3;
            }
            return result;
        }
    }
}",
