using System;

namespace MyApp
{
    public static class MathOperations
    {
        /// <summary>
        /// Sorts an array of doubles in descending order and multiplies each element by 5.
        /// </summary>
        /// <param name="array">The array of doubles to process.</param>
        /// <returns>A new array with sorted and multiplied values.</returns>
        public static double[] SortDescendingAndMultiplyBy5(double[] array)
        {
            if (array == null) throw new ArgumentNullException(nameof(array));

            // Create a copy to avoid modifying the original array
            double[] result = new double[array.Length];
            Array.Copy(array, result, array.Length);

            // Sort in descending order
            Array.Sort(result);
            Array.Reverse(result);

            // Multiply each element by 5
            for (int i = 0; i < result.Length; i++)
            {
                result[i] *= 5;
            }

            return result;
        }
    }
}

