using System;
using Xunit;
using MyApp;

namespace MyApp.Tests
{
    public class MathOperationsTests
    {
        [Fact]
        public void SortDescendingAndMultiplyBy5_NullArray_ThrowsArgumentNullException()
        {
            // Arrange
            double[] array = null;

            // Act & Assert
            Assert.Throws<ArgumentNullException>(() => MathOperations.SortDescendingAndMultiplyBy5(array));
        }

        [Fact]
        public void SortDescendingAndMultiplyBy5_EmptyArray_ReturnsEmptyArray()
        {
            // Arrange
            double[] array = Array.Empty<double>();

            // Act
            double[] result = MathOperations.SortDescendingAndMultiplyBy5(array);

            // Assert
            Assert.Empty(result);
        }

        [Fact]
        public void SortDescendingAndMultiplyBy5_SingleElementArray_ReturnsMultipliedElement()
        {
            // Arrange
            double[] array = { 2.0 };

            // Act
            double[] result = MathOperations.SortDescendingAndMultiplyBy5(array);

            // Assert
            Assert.Equal(new[] { 10.0 }, result);
        }

        [Fact]
        public void SortDescendingAndMultiplyBy5_NormalArray_ReturnsSortedAndMultiplied()
        {
            // Arrange
            double[] array = { 1.0, 3.0, 2.0 };

            // Act
            double[] result = MathOperations.SortDescendingAndMultiplyBy5(array);

            // Assert
            // Expected: sorted descending [3,2,1] then multiplied by 5 -> [15,10,5]
            Assert.Equal(new[] { 15.0, 10.0, 5.0 }, result);
        }

        [Fact]
        public void SortDescendingAndMultiplyBy5_WithNegativeNumbers_ReturnsSortedAndMultiplied()
        {
            // Arrange
            double[] array = { -1.0, -3.0, 2.0 };

            // Act
            double[] result = MathOperations.SortDescendingAndMultiplyBy5(array);

            // Assert
            // Sorted descending: [2, -1, -3] then multiplied by 5 -> [10, -5, -15]
            Assert.Equal(new[] { 10.0, -5.0, -15.0 }, result);
        }
    }
}

