using System;

namespace Utils
{
    public static class ArrayUtils
    {
        /// <summary>
        /// Sorts an array of doubles in descending order, then multiplies each element (except the first) with the previous element.
        /// The first element remains unchanged.
        /// </summary>
        /// <param name="arr">The input array of doubles.</param>
        /// <returns>A new array where the first element is the largest, and each subsequent element is the product of the sorted element and its predecessor.</returns>
        /// <exception cref="ArgumentNullException">If arr is null.</exception>
        public static double[] SortAndMultiply(double[] arr)
        {
            if (arr == null)
                throw new ArgumentNullException(nameof(arr));

            // Clone and sort descending
            double[] sorted = (double[])arr.Clone();
            Array.Sort(sorted);
            Array.Reverse(sorted); // now in descending order

