using System;

namespace MyMathLib
{
    public class Class1
    {
        /// <summary>
        /// Sorts an array of doubles in descending order and then multiplies each element by 10.
        /// </summary>
        /// <param name="arr">The array of doubles to process.</param>
        /// <returns>A new array with sorted and multiplied values.</returns>
        public static double[] SortAndMultiply(double[] arr)
        {
            if (arr == null)
                throw new ArgumentNullException(nameof(arr));

            // Create a copy to avoid modifying the original array
            double[] result = new double[arr.Length];
            Array.Copy(arr, result, arr.Length);

            // Sort in descending order
            Array.Sort(result);
            Array.Reverse(result);

            // Multiply each element by 10
            for (int i = 0; i < result.Length; i++)
            {
                result[i] *= 10;
            }

            return result;
        }
    }
}

