/// <summary>
/// Sorts an array of doubles in descending order and then multiplies each element by the specified multiplier.
/// </summary>
/// <param name="arr">The array of doubles to process.</param>
/// <param name="multiplier">The value to multiply each element by.</param>
/// <returns>A new array with sorted and multiplied values.</returns>
public static double[] SortAndMultiply(double[] arr, double multiplier)
{
    if (arr == null)
        throw new ArgumentNullException(nameof(arr));

    // Create a copy to avoid modifying the original array
    double[] result = new double[arr.Length];
    Array.Copy(arr, result, arr.Length);

    // Sort in descending order
    Array.Sort(result);
    Array.Reverse(result);

    // Multiply each element by the multiplier
    for (int i = 0; i < result.Length; i++)
    {
        result[i] *= multiplier;
    }

    return result;
}

